mapper.select:
SELECT *
FROM (
    SELECT paged.*, ROWNUM AS rn
    FROM (


        ORDER BY f.id DESC
    ) paged
    WHERE ROWNUM <= #{offset} + #{size}
)
WHERE rn > #{offset}


ORDER BY rn

